// Package lru implements a fixed-capacity least-recently-used cache with
// O(1) expected-time operations.
package lru

const nilSlot = -1

// entry is a slot in the cache's slab. Recency order is an intrusive doubly
// linked list over slot indices.
type entry struct {
	key, value string
	prev, next int32
}

// Cache is a string-keyed LRU cache. The zero value is not usable; create
// one with New.
type Cache struct {
	capacity int
	index    map[string]int32
	entries  []entry
	free     []int32
	head     int32 // most recently used
	tail     int32 // least recently used
}

// maxPrealloc bounds the up-front allocation so that very large capacities
// do not reserve memory that may never be used.
const maxPrealloc = 1 << 16

// New returns an empty cache holding at most capacity keys.
// It panics if capacity is less than 1.
func New(capacity int) *Cache {
	if capacity < 1 {
		panic("lru: capacity must be positive")
	}
	hint := min(capacity, maxPrealloc)
	return &Cache{
		capacity: capacity,
		index:    make(map[string]int32, hint),
		entries:  make([]entry, 0, hint),
		head:     nilSlot,
		tail:     nilSlot,
	}
}

// Len reports the number of keys held.
func (c *Cache) Len() int { return len(c.index) }

// Get returns the value for key and marks it most recently used.
func (c *Cache) Get(key string) (string, bool) {
	slot, ok := c.index[key]
	if !ok {
		return "", false
	}
	c.moveToFront(slot)
	return c.entries[slot].value, true
}

// GetBytes is like Get but takes the key as a byte slice, avoiding an
// allocation for the lookup.
func (c *Cache) GetBytes(key []byte) (string, bool) {
	slot, ok := c.index[string(key)]
	if !ok {
		return "", false
	}
	c.moveToFront(slot)
	return c.entries[slot].value, true
}

// Set inserts or overwrites key, marking it most recently used. If the cache
// is full, the least recently used key is evicted first.
func (c *Cache) Set(key, value string) {
	if slot, ok := c.index[key]; ok {
		c.entries[slot].value = value
		c.moveToFront(slot)
		return
	}
	if len(c.index) >= c.capacity {
		c.evictLeastRecent()
	}

	var slot int32
	if n := len(c.free); n > 0 {
		slot = c.free[n-1]
		c.free = c.free[:n-1]
	} else {
		slot = int32(len(c.entries))
		c.entries = append(c.entries, entry{})
	}
	c.entries[slot].key = key
	c.entries[slot].value = value
	c.index[key] = slot
	c.pushFront(slot)
}

// Delete removes key and reports whether it was present.
func (c *Cache) Delete(key string) bool {
	slot, ok := c.index[key]
	if !ok {
		return false
	}
	c.removeSlot(slot)
	return true
}

// DeleteBytes is like Delete but takes the key as a byte slice.
func (c *Cache) DeleteBytes(key []byte) bool {
	slot, ok := c.index[string(key)]
	if !ok {
		return false
	}
	c.removeSlot(slot)
	return true
}

func (c *Cache) evictLeastRecent() {
	if c.tail != nilSlot {
		c.removeSlot(c.tail)
	}
}

func (c *Cache) removeSlot(slot int32) {
	e := &c.entries[slot]
	delete(c.index, e.key)
	c.unlink(slot)
	e.key, e.value = "", ""
	c.free = append(c.free, slot)
}

func (c *Cache) moveToFront(slot int32) {
	if slot == c.head {
		return
	}
	c.unlink(slot)
	c.pushFront(slot)
}

func (c *Cache) pushFront(slot int32) {
	e := &c.entries[slot]
	e.prev = nilSlot
	e.next = c.head
	if c.head != nilSlot {
		c.entries[c.head].prev = slot
	}
	c.head = slot
	if c.tail == nilSlot {
		c.tail = slot
	}
}

func (c *Cache) unlink(slot int32) {
	e := &c.entries[slot]
	p, n := e.prev, e.next
	if p != nilSlot {
		c.entries[p].next = n
	} else {
		c.head = n
	}
	if n != nilSlot {
		c.entries[n].prev = p
	} else {
		c.tail = p
	}
}

package lru

import "testing"

func TestEvictionOrder(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	c.Set("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
	if c.Len() != 2 {
		t.Fatalf("Len = %d; want 2", c.Len())
	}
}

func TestOverwriteRefreshes(t *testing.T) {
	c := New(2)
	c.Set("a", "1")
	c.Set("b", "2")
	c.Set("a", "9")
	c.Set("c", "3")
	if v, _ := c.Get("a"); v != "9" {
		t.Fatalf("Get(a) = %q; want 9", v)
	}
	if _, ok := c.Get("b"); ok {
		t.Fatal("b should have been evicted")
	}
}

func TestDeleteReusesSlots(t *testing.T) {
	c := New(3)
	c.Set("x", "1")
	if !c.Delete("x") || c.Delete("x") {
		t.Fatal("Delete should report presence exactly once")
	}
	for i := range 10 {
		c.Set(string(rune('a'+i)), "v")
	}
	if c.Len() != 3 || len(c.entries) > 3 {
		t.Fatalf("Len = %d, slots = %d; want 3, <=3", c.Len(), len(c.entries))
	}
	for _, k := range []string{"h", "i", "j"} {
		if _, ok := c.Get(k); !ok {
			t.Fatalf("%s missing", k)
		}
	}
}

// Command app simulates an LRU cache driven by commands on standard input.
// See SPEC.md for the input format.
package main

import (
	"bufio"
	"bytes"
	"fmt"
	"io"
	"os"
	"strconv"

	"lru-sim/lru"
)

const nullReply = "NULL"

func main() {
	input, err := io.ReadAll(os.Stdin)
	if err != nil {
		fmt.Fprintln(os.Stderr, "read stdin:", err)
		os.Exit(1)
	}
	w := bufio.NewWriterSize(os.Stdout, 64<<10)
	if err := run(input, w); err != nil {
		fmt.Fprintln(os.Stderr, "write stdout:", err)
		os.Exit(1)
	}
	if err := w.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, "write stdout:", err)
		os.Exit(1)
	}
}

// run executes the command script in input, writing one reply per line to w.
// Malformed lines and unknown commands are ignored. If the capacity line is
// invalid, nothing is written.
func run(input []byte, w *bufio.Writer) error {
	first, rest, _ := bytes.Cut(input, []byte{'\n'})
	capacity, ok := parseCapacity(first)
	if !ok {
		return nil
	}
	cache := lru.New(capacity)
	var num []byte

	for len(rest) > 0 {
		var line []byte
		line, rest, _ = bytes.Cut(rest, []byte{'\n'})
		line = bytes.TrimSuffix(line, []byte{'\r'})
		if len(line) == 0 {
			continue
		}

		command, arg, _ := bytes.Cut(line, []byte{' '})
		switch string(command) {
		case "SET":
			key, value, found := bytes.Cut(arg, []byte{' '})
			if found {
				cache.Set(string(key), string(value))
			}
			continue
		case "GET":
			if v, ok := cache.GetBytes(arg); ok {
				w.WriteString(v)
			} else {
				w.WriteString(nullReply)
			}
		case "DEL":
			if cache.DeleteBytes(arg) {
				w.WriteByte('1')
			} else {
				w.WriteByte('0')
			}
		case "SIZE":
			num = strconv.AppendInt(num[:0], int64(cache.Len()), 10)
			w.Write(num)
		default:
			continue
		}
		if err := w.WriteByte('\n'); err != nil {
			return err
		}
	}
	return nil
}

// parseCapacity reads a leading integer from line with the leniency of
// JavaScript's parseInt: leading whitespace is skipped, an optional sign is
// accepted, and anything after the digits is ignored. It reports false when
// no digits are found or the value is less than 1. Values too large to
// represent saturate, which is equivalent to an unbounded cache.
func parseCapacity(line []byte) (int, bool) {
	i := 0
	for i < len(line) && isSpace(line[i]) {
		i++
	}
	negative := false
	if i < len(line) && (line[i] == '+' || line[i] == '-') {
		negative = line[i] == '-'
		i++
	}
	const limit = 1 << 40
	n, digits := 0, 0
	for ; i < len(line) && '0' <= line[i] && line[i] <= '9'; i++ {
		if n < limit {
			n = n*10 + int(line[i]-'0')
		}
		digits++
	}
	if digits == 0 || negative || n < 1 {
		return 0, false
	}
	return n, true
}

// isSpace reports whether b (interpreted as Latin-1) is JavaScript whitespace.
func isSpace(b byte) bool {
	switch b {
	case '\t', '\n', '\v', '\f', '\r', ' ', 0xA0:
		return true
	}
	return false
}
